(() => {
  'use strict';

  const fmt = new Intl.NumberFormat('ru-RU');
  const money = new Intl.NumberFormat('ru-RU', { style: 'currency', currency: 'RUB', maximumFractionDigits: 0 });
  const num = v => Number(v || 0);
  const sum = (arr, key) => (arr || []).reduce((a, x) => a + num(typeof key === 'function' ? key(x) : x?.[key]), 0);
  const avg = (arr, key) => (arr || []).length ? sum(arr, key) / arr.length : 0;
  const median = values => { const a = (values || []).map(num).filter(Number.isFinite).sort((x,y)=>x-y); if(!a.length)return 0; const m=Math.floor(a.length/2); return a.length%2?a[m]:(a[m-1]+a[m])/2; };
  const pct = (v, d=1) => v === null || v === undefined || !Number.isFinite(Number(v)) ? '—' : `${Number(v).toFixed(d).replace('.', ',')}%`;
  const esc = s => String(s ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const iso = d => new Date(d).toISOString().slice(0,10);
  const dateRu = s => s ? new Date(`${String(s).slice(0,10)}T12:00:00`).toLocaleDateString('ru-RU',{day:'2-digit',month:'short'}) : '—';
  const dateTimeRu = s => s ? new Date(s.replace(' ','T')+'Z').toLocaleString('ru-RU') : '—';
  const duration = sec => { const s=Math.max(0,Math.round(num(sec))); return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`; };
  const clamp = (x,a,b) => Math.max(a,Math.min(b,x));
  const relDelta = (current, previous) => previous ? (current-previous)/previous*100 : null;
  const ppDelta = (current, previous) => Number.isFinite(current)&&Number.isFinite(previous) ? current-previous : null;
  const dayStart = (days, offset=0) => { const d=new Date(); d.setHours(0,0,0,0); d.setDate(d.getDate()-(days-1)-offset); return d; };
  const inWindow = (date, days, offset=0) => { if(!date)return false; const d=new Date(`${String(date).slice(0,10)}T12:00:00`); const start=dayStart(days,offset); const end=dayStart(1,offset); end.setHours(23,59,59,999); return d>=start&&d<=end; };
  const statusLabel = s => ({ok:'Синхронизировано',partial:'Частично',pending:'Ожидает',error:'Ошибка'}[s] || 'Нет синхронизации');

  const blank = () => ({
    site:[], sitePeriods:{}, sources:[], pages:[], searchEngines:[], searchPhrases:[], utm:[], devices:[], regions:[], goals:[],
    seo:[], seoSummary:null, seoIndex:[], seoProblems:[],
    adsMeta:[], adsDaily:[], social:[], socialDaily:[], email:[], emailLinks:[], syncLog:[],
    meta:{metrikaCounterId:null,webmasterHostId:null,vkGroupId:null,siteUrl:null,goalMapping:{email:[],forms:[]}}
  });

  let state = blank();
  let apiStatus = { mode:'empty', integrations:{}, runtime:{} };
  let charts = {};
  let currentUser = null;
  let adChannelFilter = 'Все';
  const AUTH_TOKEN_KEY='cs-marketing-auth-token-v4';
  const LOCAL_KEY='cs-marketing-v12-local';
  const local = (()=>{try{return JSON.parse(localStorage.getItem(LOCAL_KEY)||'{}')}catch{return {}}})();
  const saveLocal=()=>{try{localStorage.setItem(LOCAL_KEY,JSON.stringify({manualTasks:local.manualTasks||[],doneTasks:local.doneTasks||{}}))}catch{}};
  const getToken=()=>{try{return sessionStorage.getItem(AUTH_TOKEN_KEY)||''}catch{return ''}};
  const setToken=t=>{try{t?sessionStorage.setItem(AUTH_TOKEN_KEY,t):sessionStorage.removeItem(AUTH_TOKEN_KEY)}catch{}};

  async function apiFetch(url,options={}){const h=new Headers(options.headers||{}),t=getToken();if(t&&!h.has('Authorization'))h.set('Authorization',`Bearer ${t}`);return fetch(url,{...options,headers:h,credentials:'include',cache:'no-store'});}
  function showAlert(text,type=''){const el=document.getElementById('globalAlert');el.textContent=text;el.className=`alert ${type}`;el.hidden=false;clearTimeout(showAlert.t);showAlert.t=setTimeout(()=>el.hidden=true,7000);}

  function showAuth(message=''){currentUser=null;document.getElementById('appShell').hidden=true;document.getElementById('authScreen').hidden=false;const e=document.getElementById('authError');e.textContent=message;e.hidden=!message;document.getElementById('passwordInput').value='';}
  async function showApp(user){currentUser=user||'admin';document.getElementById('authScreen').hidden=true;document.getElementById('appShell').hidden=false;document.getElementById('accountName').textContent=currentUser;renderAll();await Promise.all([fetchStatus(),loadData()]);}
  async function initAuth(){try{const r=await apiFetch('/api/auth/session');const d=await r.json().catch(()=>({}));if(r.ok&&d.authenticated)return showApp(d.user);setToken('');showAuth();}catch(e){showAuth(`Не удалось связаться с сервером: ${e.message||'ошибка сети'}`)}}
  async function login(e){e.preventDefault();const btn=document.getElementById('loginBtn'),err=document.getElementById('authError');err.hidden=true;btn.disabled=true;btn.textContent='Проверяю…';try{const r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',cache:'no-store',body:JSON.stringify({username:document.getElementById('loginInput').value.trim(),password:document.getElementById('passwordInput').value})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||`Ошибка входа ${r.status}`);if(d.token)setToken(d.token);await showApp(d.user||'admin');}catch(ex){err.textContent=ex.message||'Не удалось войти';err.hidden=false;}finally{btn.disabled=false;btn.textContent='Войти';}}
  async function logout(){try{await apiFetch('/api/auth/logout',{method:'POST'})}catch{}setToken('');showAuth();}

  async function fetchStatus(){try{const r=await apiFetch('/api/status');if(!r.ok)throw new Error();apiStatus=await r.json();renderIntegrations();renderHealth();}catch{showAlert('Не удалось проверить состояние интеграций.','error')}}
  async function loadData(){try{const r=await apiFetch('/api/dashboard');if(!r.ok)throw new Error();state={...blank(),...(await r.json())};renderAll();}catch{showAlert('Не удалось загрузить аналитические данные.','error');renderAll();}}
  async function syncOne(source){showAlert(`Синхронизация: ${source}…`);try{const r=await apiFetch(`/api/sync/${source}`,{method:'POST'});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Ошибка синхронизации');showAlert(d.message||'Источник обновлён','success');await Promise.all([loadData(),fetchStatus()]);}catch(e){showAlert(e.message||'Синхронизация не выполнена','error')}}
  async function syncAll(){showAlert('Обновляю все источники, включая VK, Telegram, MAX и Дзен…');try{const r=await apiFetch('/api/sync/all',{method:'POST'});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Ошибка общей синхронизации');showAlert(d.message||'Данные обновлены','success');await Promise.all([loadData(),fetchStatus()]);}catch(e){showAlert(e.message||'Синхронизация не выполнена','error')}}

  function destroyChart(id){if(charts[id]){charts[id].destroy();delete charts[id];}}
  function chart(id,type,data,options={}){const c=document.getElementById(id);if(!c||!window.Chart)return;destroyChart(id);charts[id]=new Chart(c,{type,data,options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:false},tooltip:{enabled:true}},scales:type==='doughnut'?{}:{x:{grid:{display:false},ticks:{color:'#8a94a6',maxRotation:0}},y:{beginAtZero:true,grid:{color:'#edf0f4'},ticks:{color:'#8a94a6'}}},...options}});}
  function metricGrid(id,items){const el=document.getElementById(id);if(!el)return;el.innerHTML=items.map(x=>`<article class="metric-card"><div class="metric-top"><div class="metric-title">${esc(x.title)}</div>${x.delta===undefined||x.delta===null?'':`<span class="delta ${x.delta>0?'up':x.delta<0?'down':'flat'}">${x.delta>0?'+':''}${Number(x.delta).toFixed(1).replace('.',',')}%</span>`}</div><div class="metric-value">${x.value}</div><div class="metric-note">${esc(x.note||'')}</div></article>`).join('');}
  function pill(text,cls='info'){return `<span class="status ${cls}">${esc(text)}</span>`;}
  function issueHtml(x){return `<div class="issue-item"><div class="issue-icon ${x.level}">${x.level==='high'?'!':x.level==='medium'?'↗':'i'}</div><div><div class="issue-title">${esc(x.title)}</div><div class="issue-text">${esc(x.text)}</div>${x.action?`<div class="issue-action">${esc(x.action)}</div>`:''}${x.evidence?`<div class="issue-evidence">${esc(x.evidence)}</div>`:''}</div></div>`;}
  function rowsFor(arr,days,offset=0){return (arr||[]).filter(x=>inWindow(x.date,days,offset));}

  function siteSummary(days,offset=0){const rows=rowsFor(state.site,days,offset);if(!rows.length)return null;const visits=sum(rows,'visits');return {visits,users:sum(rows,'users'),pageviews:sum(rows,'pageviews'),bounce:visits?sum(rows,x=>num(x.bounceRate)*num(x.visits))/visits:avg(rows,'bounceRate'),depth:visits?sum(rows,x=>num(x.depth)*num(x.visits))/visits:avg(rows,'depth'),duration:visits?sum(rows,x=>num(x.duration)*num(x.visits))/visits:avg(rows,'duration'),newVisitors:visits?sum(rows,x=>num(x.newVisitors)*num(x.visits))/visits:avg(rows,'newVisitors'),goals:sum(rows,'conversions'),emailClicks:sum(rows,'emailClicks'),formSubmits:sum(rows,'formSubmits')};}
  function siteCompare(days){const c=siteSummary(days),p=siteSummary(days,days);return {c,p,d:(k)=>c&&p?relDelta(num(c[k]),num(p[k])):null};}
  function seoSummary(){if(!state.seo.length&&!state.seoSummary)return null;const shows=sum(state.seo,'shows'),clicks=sum(state.seo,'clicks');const weightedPos=shows?sum(state.seo,x=>num(x.position)*num(x.shows))/shows:avg(state.seo,'position');return {shows,clicks,ctr:shows?clicks/shows*100:0,position:weightedPos,...(state.seoSummary||{})};}
  function aggregateAds(days,channel='Все',offset=0){const rows=rowsFor(state.adsDaily,days,offset).filter(x=>channel==='Все'||x.channel===channel),meta=(state.adsMeta||[]).filter(x=>channel==='Все'||x.channel===channel),map=new Map();meta.forEach(m=>map.set(`${m.channel}|${m.campaignId}`,{...m,impressions:0,clicks:0,spend:0,conversions:0,bounceWeighted:0,depthWeighted:0,behaviorVisits:0}));rows.forEach(r=>{const k=`${r.channel}|${r.campaignId}`;const v=map.get(k)||{channel:r.channel,campaignId:r.campaignId,name:r.name,status:'unknown',nativeState:'',impressions:0,clicks:0,spend:0,conversions:0,bounceWeighted:0,depthWeighted:0,behaviorVisits:0};v.impressions+=num(r.impressions);v.clicks+=num(r.clicks);v.spend+=num(r.spend);v.conversions+=num(r.conversions);if(num(r.clicks)){v.bounceWeighted+=num(r.bounceRate)*num(r.clicks);v.depthWeighted+=num(r.avgPageviews)*num(r.clicks);v.behaviorVisits+=num(r.clicks);}map.set(k,v)});return [...map.values()].map(x=>({...x,ctr:x.impressions?x.clicks/x.impressions*100:0,cpc:x.clicks?x.spend/x.clicks:0,cvr:x.clicks?x.conversions/x.clicks*100:0,cpa:x.conversions?x.spend/x.conversions:null,bounceRate:x.behaviorVisits?x.bounceWeighted/x.behaviorVisits:0,avgPageviews:x.behaviorVisits?x.depthWeighted/x.behaviorVisits:0}));}
  function adTotals(rows){const impressions=sum(rows,'impressions'),clicks=sum(rows,'clicks'),spend=sum(rows,'spend'),conversions=sum(rows,'conversions');return {impressions,clicks,spend,conversions,ctr:impressions?clicks/impressions*100:0,cpc:clicks?spend/clicks:0,cvr:clicks?conversions/clicks*100:0,cpa:conversions?spend/conversions:null};}
  function socialChannelSummary(days,channel,offset=0){const daily=rowsFor(state.socialDaily,days,offset).filter(x=>x.channel===channel),posts=rowsFor(state.social,days,offset).filter(x=>x.channel===channel);if(!daily.length&&!posts.length)return null;const views=daily.length?sum(daily,'views'):sum(posts,'views'),reach=daily.length?sum(daily,'reach'):sum(posts,'reach'),interactions=sum(posts,x=>num(x.reactions)+num(x.comments)+num(x.shares)),subscribed=sum(daily,'subscribed'),unsubscribed=sum(daily,'unsubscribed'),followers=(posts.find(x=>num(x.followers)>0)||state.social.find(x=>x.channel===channel&&num(x.followers)>0))?.followers||0;return {channel,views,reach,interactions,subscribed,unsubscribed,net:subscribed-unsubscribed,posts:posts.length,followers:num(followers),er:views?interactions/views*100:0,visitors:sum(daily,'visitors'),avgViews:posts.length?sum(posts,'views')/posts.length:0};}
  function socialChannels(days,offset=0){return [...new Set([...(state.social||[]).map(x=>x.channel),...(state.socialDaily||[]).map(x=>x.channel)])].map(ch=>socialChannelSummary(days,ch,offset)).filter(Boolean);}
  function socialSummary(days,offset=0){const channels=socialChannels(days,offset);if(!channels.length)return null;const posts=channels.reduce((a,x)=>a+x.posts,0),views=channels.reduce((a,x)=>a+x.views,0),reach=channels.reduce((a,x)=>a+x.reach,0),interactions=channels.reduce((a,x)=>a+x.interactions,0),followers=channels.reduce((a,x)=>a+x.followers,0),subscribed=channels.reduce((a,x)=>a+x.subscribed,0),unsubscribed=channels.reduce((a,x)=>a+x.unsubscribed,0);return {channels:channels.length,views,reach,interactions,followers,subscribed,unsubscribed,net:subscribed-unsubscribed,posts,er:views?interactions/views*100:0,visitors:channels.reduce((a,x)=>a+x.visitors,0),avgViews:posts?sum(rowsFor(state.social,days,offset),'views')/posts:0,byChannel:channels};}
  function emailSummary(days,offset=0){const rows=rowsFor(state.email,days,offset);if(!rows.length)return null;const sent=sum(rows,'sent'),delivered=sum(rows,'delivered'),opened=sum(rows,'opened'),clicked=sum(rows,'clicked'),unsub=sum(rows,'unsub'),spam=sum(rows,'spam'),errors=sum(rows,'errors');return {campaigns:rows.length,sent,delivered,opened,clicked,unsub,spam,errors,delivery:sent?delivered/sent*100:0,openRate:delivered?opened/delivered*100:0,ctr:delivered?clicked/delivered*100:0,ctor:opened?clicked/opened*100:0,unsubRate:delivered?unsub/delivered*100:0,spamRate:delivered?spam/delivered*100:0};}
  function normalizedStatus(s){const v=String(s||'').toLowerCase();if(['active','on'].includes(v))return ['Активна','good'];if(['suspended','blocked'].includes(v))return ['Остановлена','warn'];if(['ended','archived','deleted','converted'].includes(v))return ['Завершена','muted'];if(['inactive','off'].includes(v))return ['Неактивна','muted'];return ['Неизвестно','info'];}

  function sourceQuality(source, siteCr){const cr=num(source.visits)?num(source.conversions)/num(source.visits)*100:0;if(num(source.visits)<5)return ['Мало данных','muted'];if(cr>siteCr*1.35&&cr>0)return ['Сильный','good'];if(num(source.bounce)>50&&cr<siteCr*.7)return ['Слабый','bad'];return ['Нормально','info'];}
  function pageSignal(p,avgCr){const cr=num(p.visits)?num(p.conversions)/num(p.visits)*100:0;if(num(p.visits)>=10&&num(p.bounce)>55&&num(p.duration)<60)return ['Теряет трафик','bad'];if(num(p.visits)>=10&&cr>avgCr*1.5&&cr>0)return ['Конвертирует','good'];if(num(p.visits)>=20&&cr===0)return ['Нет целей','warn'];return ['Без сигнала','muted'];}

  function insights(days){
    const out=[], positives=[]; const sc=siteCompare(days),seo=seoSummary(),ads=aggregateAds(days),ad=adTotals(ads),adsPrev=adTotals(aggregateAds(days,'Все',days)),soc=socialSummary(days),socPrev=socialSummary(days,days),em=emailSummary(days),emPrev=emailSummary(days,days);
    if(!sc.c)out.push({level:'high',area:'Сайт',title:'Нет данных Метрики',text:'Без Метрики невозможно оценить трафик, заявки и поведение.',action:'Запустить синхронизацию Яндекс Метрики.'});
    if(sc.c&&sc.p){const d=relDelta(sc.c.visits,sc.p.visits);if(d<-20)out.push({level:'high',area:'Сайт',title:`Посещаемость снизилась на ${Math.abs(d).toFixed(0)}%`,text:`За период ${fmt.format(sc.c.visits)} визитов против ${fmt.format(sc.p.visits)} ранее.`,action:'Разобрать источники падения и страницы входа.',evidence:'Сравнение с предыдущим равным периодом.'});else if(d>20)positives.push(`Посещаемость выросла на ${d.toFixed(0)}%.`);
      const cr=sc.c.visits?sc.c.formSubmits/sc.c.visits*100:0,pr=sc.p.visits?sc.p.formSubmits/sc.p.visits*100:0,dc=relDelta(cr,pr);if(sc.c.formSubmits===0&&sc.c.visits>=20)out.push({level:'high',area:'Сайт',title:'Заявок нет при наличии трафика',text:`Есть ${fmt.format(sc.c.visits)} визитов, но цель формы не достигалась.`,action:'Проверить работу формы, цель Метрики и путь пользователя до заявки.'});else if(dc!==null&&dc<-25)out.push({level:'high',area:'Сайт',title:'Конверсия формы просела',text:`CR формы ${pct(cr)} против ${pct(pr)} в предыдущем периоде.`,action:'Открыть Вебвизор по страницам входа и проверить форму.'});else if(dc!==null&&dc>25)positives.push(`Конверсия формы выросла до ${pct(cr)}.`);
      if(sc.c.bounce-sc.p.bounce>10)out.push({level:'medium',area:'Сайт',title:'Отказы заметно выросли',text:`Отказы ${pct(sc.c.bounce)}, изменение +${(sc.c.bounce-sc.p.bounce).toFixed(1)} п.п.`,action:'Смотреть источники и страницы с высоким отказом.'});
    }
    const siteCr=sc.c?.visits?sc.c.formSubmits/sc.c.visits*100:0;
    const badPages=(state.pages||[]).filter(p=>num(p.visits)>=10&&num(p.bounce)>55&&num(p.duration)<60).slice(0,3);if(badPages.length)out.push({level:'medium',area:'Сайт',title:`${badPages.length} страницы теряют входящий трафик`,text:badPages.map(p=>shortUrl(p.page)).join(', '),action:'Проверить первый экран, соответствие запросу и мобильную версию.'});
    if(seo){const critical=num(seo.fatal)+num(seo.critical);if(critical>0)out.push({level:'high',area:'SEO',title:`${critical} критических проблем Вебмастера`,text:'Технические ошибки могут ограничивать индексацию или видимость.',action:'Сначала закрыть Fatal/Critical из диагностики.'});const drops=(state.seo||[]).filter(q=>num(q.delta)<=-3&&num(q.shows)>=20).sort((a,b)=>a.delta-b.delta);if(drops.length)out.push({level:'high',area:'SEO',title:'Есть запросы с заметной потерей позиций',text:drops.slice(0,3).map(q=>`${q.query} (${q.delta.toFixed(1)})`).join('; '),action:'Проверить страницы, сниппеты и изменения конкурентов.'});const wins=(state.seo||[]).filter(q=>num(q.delta)>=3&&num(q.shows)>=20);if(wins.length)positives.push(`${wins.length} поисковых запросов заметно выросли по позиции.`);}
    const active=ads.filter(x=>normalizedStatus(x.status)[0]==='Активна');active.filter(x=>x.spend>0&&x.conversions===0&&x.clicks>=10).slice(0,3).forEach(x=>out.push({level:'high',area:'Реклама',title:`«${x.name}» тратит бюджет без конверсий`,text:`Расход ${money.format(x.spend)}, ${fmt.format(x.clicks)} кликов, 0 конверсий.`,action:'Проверить запросы/аудиторию, посадочную страницу и цели.'}));if(ad.spend>0&&adsPrev.spend>0){const ds=relDelta(ad.spend,adsPrev.spend),dc=relDelta(ad.conversions,adsPrev.conversions);if(ds>25&&(dc===null||dc<5))out.push({level:'medium',area:'Реклама',title:'Расход растёт быстрее результата',text:`Расход +${ds.toFixed(0)}%, конверсии ${dc===null?'без базы сравнения':`${dc>0?'+':''}${dc.toFixed(0)}%`}.`,action:'Перераспределить бюджет в кампании с лучшим CPA.'});}
    if(soc&&socPrev){const dv=relDelta(soc.views,socPrev.views);if(dv!==null&&dv<-25)out.push({level:'medium',area:'Соцсети',title:'Просмотры контента снизились',text:`Изменение ${dv.toFixed(0)}% к предыдущему периоду по доступным VK/Telegram/MAX данным.`,action:'Разобрать темы и форматы лучших публикаций отдельно по каждому каналу.'});if(soc.net<0)out.push({level:'medium',area:'Соцсети',title:'По VK отток подписчиков выше притока',text:`Чистое изменение: ${soc.net}.`,action:'Проверить частоту публикаций и темы VK периода.'});}
    if(em){if(em.delivery<95)out.push({level:'high',area:'Email',title:'Доставляемость ниже 95%',text:`Delivery rate ${pct(em.delivery)}.`,action:'Проверить качество базы, доменную аутентификацию и причины недоставки.'});if(em.spamRate>.1)out.push({level:'high',area:'Email',title:'Жалобы на спам требуют внимания',text:`Spam rate ${pct(em.spamRate,2)}.`,action:'Проверить сегментацию, частоту и ожидания подписчиков.'});if(emPrev){const dc=relDelta(em.ctr,emPrev.ctr);if(dc!==null&&dc<-25)out.push({level:'medium',area:'Email',title:'CTR рассылок снизился',text:`CTR ${pct(em.ctr)} против ${pct(emPrev.ctr)} ранее.`,action:'Сравнить темы и CTA лучших и слабых писем.'});}}
    if(state.utm?.length===0&&sc.c?.visits>=20)out.push({level:'medium',area:'Атрибуция',title:'UTM-данные не найдены',text:'Без UTM собственные каналы и размещения будут смешиваться в Метрике.',action:'Проверить UTM-разметку ссылок из VK, email, Дзена и рекламных размещений.'});
    return {issues:out,positives,siteCr};
  }

  function seoRecommendations(){const out=[],s=seoSummary();if(!s)return [{level:'high',title:'Сначала подключить Вебмастер',text:'Плана SEO без данных поисковых запросов и диагностики нет.',action:'Синхронизировать Яндекс Вебмастер.'}];const crit=num(s.fatal)+num(s.critical);if(crit)out.push({level:'high',title:'Техническая база',text:`Закрыть ${crit} критических ошибок Вебмастера до масштабных контентных изменений.`,action:'Исправить Fatal/Critical и повторно проверить индексацию.'});const drops=(state.seo||[]).filter(q=>q.delta<=-2&&q.shows>=20).sort((a,b)=>a.delta-b.delta).slice(0,5);if(drops.length)out.push({level:'high',title:'Вернуть потерянные позиции',text:drops.map(q=>`«${q.query}»`).join(', '),action:'Сопоставить запросы с посадочными страницами, проверить Title/H1/контент и внутренние ссылки.'});const quick=(state.seo||[]).filter(q=>q.position>=4&&q.position<=15&&q.shows>=20).sort((a,b)=>b.shows-a.shows).slice(0,6);if(quick.length)out.push({level:'medium',title:'Дожать запросы рядом с топом',text:quick.map(q=>`«${q.query}» — ${q.position.toFixed(1)}`).join('; '),action:'Усилить релевантность страниц, сниппеты и перелинковку.'});const ctr=(state.seo||[]).filter(q=>q.position<=10&&q.shows>=30&&q.ctr<2).sort((a,b)=>b.shows-a.shows).slice(0,5);if(ctr.length)out.push({level:'medium',title:'Поднять CTR сниппетов',text:ctr.map(q=>`«${q.query}» — ${pct(q.ctr)}`).join('; '),action:'Переписать Title/Description под интент и конкретную выгоду страницы.'});const badPages=(state.pages||[]).filter(p=>p.visits>=10&&p.bounce>55&&p.duration<60).slice(0,5);if(badPages.length)out.push({level:'medium',title:'Улучшить страницы, которые уже получают трафик',text:badPages.map(p=>shortUrl(p.page)).join(', '),action:'Сначала улучшать страницы с реальным входящим трафиком, а не создавать новые вслепую.'});if(!out.length)out.push({level:'low',title:'Критичных SEO-сигналов нет',text:'Можно переходить к расширению семантики и контента.',action:'Выбрать запросы 4–15 позиции с максимальными показами.'});return out;}

  function adsRecommendations(days){const a=aggregateAds(days,adChannelFilter),out=[];const active=a.filter(x=>normalizedStatus(x.status)[0]==='Активна');const cpaMedian=median(active.filter(x=>x.cpa!==null).map(x=>x.cpa)),ctrMedian=median(active.filter(x=>x.impressions>=100).map(x=>x.ctr));active.forEach(x=>{if(x.spend>0&&x.conversions===0&&x.clicks>=10)out.push({level:'high',title:`Нет конверсий: ${x.name}`,text:`${fmt.format(x.clicks)} кликов и ${money.format(x.spend)} расхода.`,action:'Проверить качество трафика и посадочную страницу.'});else if(x.cpa&&cpaMedian&&x.cpa>cpaMedian*1.6)out.push({level:'medium',title:`CPA выше медианы: ${x.name}`,text:`CPA ${money.format(x.cpa)} против медианы ${money.format(cpaMedian)}.`,action:'Снизить долю бюджета или найти причину низкой конверсии.'});if(x.impressions>=500&&ctrMedian&&x.ctr<ctrMedian*.6)out.push({level:'medium',title:`Низкий CTR относительно других кампаний`,text:`«${x.name}»: ${pct(x.ctr)} при медиане ${pct(ctrMedian)}.`,action:'Протестировать новый оффер, креатив или таргетинг.'});});return out.length?out.slice(0,8):[{level:'low',title:'Критичных рекламных сигналов нет',text:'По доступным данным активные кампании не выбиваются из собственного базового уровня.',action:'Продолжать собирать данные и сравнивать CPA/CTR между кампаниями.'}];}
  function emailRecommendations(days){const rows=rowsFor(state.email,days),out=[];if(!rows.length)return [{level:'medium',title:'Нет рассылок за период',text:'Нечего сравнивать.',action:'Синхронизировать UniSender или выбрать более длинный период.'}];const ors=rows.filter(x=>x.delivered).map(x=>x.opened/x.delivered*100),ctrs=rows.filter(x=>x.delivered).map(x=>x.clicked/x.delivered*100),orMed=median(ors),ctrMed=median(ctrs);rows.forEach(x=>{const delivery=x.sent?x.delivered/x.sent*100:0,open=x.delivered?x.opened/x.delivered*100:0,ctr=x.delivered?x.clicked/x.delivered*100:0,spam=x.delivered?x.spam/x.delivered*100:0;if(delivery<95&&x.sent>=50)out.push({level:'high',title:`Доставляемость: ${x.name}`,text:`${pct(delivery)} доставлено.`,action:'Проверить базу и причины недоставки.'});if(spam>.1)out.push({level:'high',title:`Жалобы на спам: ${x.name}`,text:`${pct(spam,2)} от доставленных.`,action:'Снизить частоту или уточнить сегмент/ожидания.'});if(x.delivered>=50&&orMed&&open<orMed*.65)out.push({level:'medium',title:`Открываемость ниже своей медианы`,text:`«${x.name}»: ${pct(open)} vs медиана ${pct(orMed)}.`,action:'Сравнить тему письма и сегмент с лучшими рассылками.'});if(x.delivered>=50&&ctrMed&&ctr<ctrMed*.6)out.push({level:'medium',title:`CTR ниже своей медианы`,text:`«${x.name}»: ${pct(ctr)} vs медиана ${pct(ctrMed)}.`,action:'Упростить CTA и проверить соответствие оффера содержанию письма.'});});return out.length?out.slice(0,8):[{level:'low',title:'Рассылки выглядят стабильно',text:'Сильных отклонений от собственной медианы не найдено.',action:'Тиражировать темы и CTA лучших кампаний.'}];}

  function marketingScore(days){let score=100;const a=insights(days).issues;score-=a.filter(x=>x.level==='high').length*12;score-=a.filter(x=>x.level==='medium').length*6;const required=['metrika','webmaster','unisender','vkads'];required.forEach(k=>{const s=apiStatus.integrations?.[k];if(!s?.configured)score-=7;else if(s.status==='error')score-=5;});return clamp(Math.round(score),0,100);}
  function managerText(days){const sc=siteCompare(days),seo=seoSummary(),ads=adTotals(aggregateAds(days)),soc=socialSummary(days),em=emailSummary(days),pack=insights(days);const lines=[];if(sc.c){const d=sc.p?relDelta(sc.c.visits,sc.p.visits):null;lines.push(`За последние ${days} дней сайт получил ${fmt.format(sc.c.visits)} визитов и ${fmt.format(sc.c.users)} посетителей${d===null?'':`, динамика к предыдущему периоду ${d>=0?'+':''}${d.toFixed(0)}%`}. Зафиксировано ${fmt.format(sc.c.formSubmits)} отправок формы и ${fmt.format(sc.c.emailClicks)} кликов по email.`);}if(seo)lines.push(`В поиске Яндекса: ${fmt.format(seo.shows)} показов, ${fmt.format(seo.clicks)} кликов, CTR ${pct(seo.ctr)}, средняя позиция ${seo.position?seo.position.toFixed(1):'—'}. Страниц в поиске: ${fmt.format(seo.searchablePages||0)}.`);if(ads.spend||ads.impressions)lines.push(`По рекламе за период: расход ${money.format(ads.spend)}, ${fmt.format(ads.clicks)} кликов и ${fmt.format(ads.conversions)} конверсий${ads.cpa!==null?`, средний CPA ${money.format(ads.cpa)}`:''}.`);if(soc)lines.push(`Соцсети: ${soc.channels} канал(а), ${fmt.format(soc.posts)} публикаций, ${fmt.format(soc.views)} просмотров и ${fmt.format(soc.interactions)} доступных взаимодействий. ${soc.byChannel.map(x=>`${x.channel}: ${fmt.format(x.posts)} пост., ${fmt.format(x.views)} просм.`).join(' ')}`);if(em)lines.push(`Email: ${em.campaigns} рассылок, доставляемость ${pct(em.delivery)}, open rate ${pct(em.openRate)}, CTR ${pct(em.ctr)}.`);if(pack.positives.length)lines.push(`Позитивные изменения: ${pack.positives.slice(0,3).join(' ')}`);const top=pack.issues.slice(0,3);if(top.length)lines.push(`Главные точки внимания: ${top.map(x=>x.title).join('; ')}.`);const plan=[...pack.issues.map(x=>x.action).filter(Boolean),...seoRecommendations().map(x=>x.action).filter(Boolean),...adsRecommendations(days).map(x=>x.action).filter(Boolean),...socialContentInsights(days,socialPostRows(days),socialChannels(days)).map(x=>x.action).filter(Boolean)].filter((x,i,a)=>a.indexOf(x)===i).slice(0,4);if(plan.length)lines.push(`Ближайшие действия: ${plan.map((x,i)=>`${i+1}) ${x}`).join(' ')}`);return lines;}

  function renderHealth(){const el=document.getElementById('healthStrip');if(!el)return;const names={metrika:'Метрика',webmaster:'Вебмастер',direct:'Директ',vkads:'VK Ads',vksocial:'VK Контент',telegram:'Telegram',maxsocial:'MAX',unisender:'UniSender'};const entries=Object.entries(names).map(([k,n])=>{const s=apiStatus.integrations?.[k]||{};let cls='muted',txt='Нет доступа';if(s.configured){cls=s.status==='error'?'bad':s.status==='partial'||s.status==='pending'?'warn':'good';txt=s.status?statusLabel(s.status):'Доступы есть';}return `<div class="health-source"><span class="health-dot ${cls}"></span><div><strong>${n}</strong><span>${txt}${s.lastSync?` · ${dateTimeRu(s.lastSync)}`:''}</span></div></div>`;});el.innerHTML=`<div class="health-title"><strong>Источники данных</strong><span>Никаких демо-цифр: только API и сохранённые реальные данные</span></div><div class="health-sources">${entries.join('')}</div>`;}

  function renderOverview(){const days=num(document.getElementById('periodSelect').value||30),sc=siteCompare(days),s=sc.c,pack=insights(days);const cr=s?.visits?s.formSubmits/s.visits*100:0,emailRate=s?.visits?s.emailClicks/s.visits*100:0,organic=(state.sources||[]).find(x=>/поиск|search/i.test(x.name)),organicShare=s?.visits?num(organic?.visits)/s.visits*100:0;metricGrid('overviewMetrics',[
    {title:'Визиты',value:s?fmt.format(s.visits):'—',delta:sc.d('visits'),note:'Яндекс Метрика'},
    {title:'Посетители',value:s?fmt.format(s.users):'—',delta:sc.d('users'),note:'уникальные за период'},
    {title:'Отправки формы',value:s?fmt.format(s.formSubmits):'—',delta:sc.d('formSubmits'),note:`CR ${s?pct(cr):'—'}`},
    {title:'Клики по email',value:s?fmt.format(s.emailClicks):'—',delta:sc.d('emailClicks'),note:`${s?pct(emailRate):'—'} от визитов`},
    {title:'Все достижения целей',value:s?fmt.format(s.goals):'—',delta:sc.d('goals'),note:'все цели Метрики'},
    {title:'Доля поиска',value:s?pct(organicShare):'—',note:'по источникам Метрики'}]);
    const rows=rowsFor(state.site,days);chart('overviewChart','line',{labels:rows.map(x=>dateRu(x.date)),datasets:[{label:'Визиты',data:rows.map(x=>x.visits),borderColor:'#4658ff',backgroundColor:'rgba(70,88,255,.08)',tension:.3,fill:true},{label:'Посетители',data:rows.map(x=>x.users),borderColor:'#7c3aed',tension:.3},{label:'Заявки',data:rows.map(x=>x.formSubmits),borderColor:'#e35454',tension:.3,yAxisID:'y1'}]},{plugins:{legend:{display:true,position:'bottom'}},scales:{x:{grid:{display:false}},y:{beginAtZero:true},y1:{beginAtZero:true,position:'right',grid:{drawOnChartArea:false}}}});
    const src=(state.sources||[]).slice(0,6);chart('sourceChart','doughnut',{labels:src.map(x=>x.name),datasets:[{data:src.map(x=>x.visits),backgroundColor:['#4658ff','#7c3aed','#0ea5e9','#10b981','#f59e0b','#94a3b8'],borderWidth:0}]},{cutout:'64%',plugins:{legend:{display:true,position:'bottom'}}});
    const siteCr=s?.visits?s.formSubmits/s.visits*100:0;document.getElementById('sourceQualityList').innerHTML=(state.sources||[]).slice(0,4).map(x=>{const [l,c]=sourceQuality(x,siteCr),cr=x.visits?x.conversions/x.visits*100:0;return `<div class="mini-row"><span>${esc(x.name)}</span><strong>${pct(cr)} ${pill(l,c)}</strong></div>`}).join('')||'<div class="empty-state">Нет данных.</div>';
    document.getElementById('overviewUtmTable').innerHTML=(state.utm||[]).slice(0,8).map(x=>`<tr><td>${esc(x.source)} / ${esc(x.medium)}</td><td>${esc(x.campaign)}</td><td>${fmt.format(x.visits)}</td><td>${fmt.format(x.conversions)}</td><td>${pct(x.visits?x.conversions/x.visits*100:0)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty-cell">UTM-данных пока нет.</td></tr>';
    const counter=state.meta?.metrikaCounterId;const btn=document.getElementById('openWebvisorBtn');btn.disabled=!counter;if(counter)btn.onclick=()=>window.open(`https://metrika.yandex.ru/visor?period=week&id=${encodeURIComponent(counter)}`,'_blank','noopener');document.getElementById('webvisorStatus').textContent=counter?'Метрика подключена':'Нет счётчика';const hints=[];if(s&&s.bounce>40)hints.push(`Сессии с отказом: общий уровень ${pct(s.bounce)}.`);if(state.pages?.some(p=>p.bounce>55&&p.visits>=10))hints.push('Смотреть страницы с высоким отказом и коротким временем.');if(s&&s.formSubmits===0&&s.visits>=20)hints.push('Проверить визиты до формы: трафик есть, заявок нет.');if(!hints.length)hints.push('Открыть последние целевые и нецелевые визиты и сравнить путь пользователя.');document.getElementById('webvisorHints').innerHTML=hints.map(x=>`<div class="hint-chip">${esc(x)}</div>`).join('');
    document.getElementById('issuesCount').textContent=`${pack.issues.length} сигналов`;document.getElementById('issueList').innerHTML=pack.issues.length?pack.issues.slice(0,6).map(issueHtml).join(''):'<div class="empty-state">По доступным данным критичных сигналов нет.</div>';document.getElementById('marketingScore').textContent=`${marketingScore(days)}/100`;document.getElementById('executiveComment').innerHTML=managerText(days).map((x,i)=>`<p>${i===0?'<strong>':''}${esc(x)}${i===0?'</strong>':''}</p>`).join('')||'<div class="empty-state">Сначала синхронизируйте источники.</div>';
  }

  function renderSite(){const days=num(document.getElementById('periodSelect').value||30),sc=siteCompare(days),s=sc.c;metricGrid('siteMetrics',[
    {title:'Визиты',value:s?fmt.format(s.visits):'—',delta:sc.d('visits'),note:'сессии'}, {title:'Посетители',value:s?fmt.format(s.users):'—',delta:sc.d('users'),note:'уникальные'}, {title:'Просмотры',value:s?fmt.format(s.pageviews):'—',delta:sc.d('pageviews'),note:'страницы'}, {title:'Отказы',value:s?pct(s.bounce):'—',note:'по Метрике'}, {title:'Глубина',value:s?num(s.depth).toFixed(2):'—',note:'страниц/визит'}, {title:'Время',value:s?duration(s.duration):'—',note:'среднее'}, {title:'Новые посетители',value:s?pct(s.newVisitors):'—',note:'доля новых'}, {title:'Все цели',value:s?fmt.format(s.goals):'—',delta:sc.d('goals'),note:'достижения'}]);
    const rows=rowsFor(state.site,days);chart('siteChart','line',{labels:rows.map(x=>dateRu(x.date)),datasets:[{label:'Визиты',data:rows.map(x=>x.visits),borderColor:'#4658ff',tension:.3},{label:'Посетители',data:rows.map(x=>x.users),borderColor:'#7c3aed',tension:.3},{label:'Просмотры',data:rows.map(x=>x.pageviews),borderColor:'#0ea5e9',tension:.3}]},{plugins:{legend:{display:true,position:'bottom'}}});
    chart('deviceChart','doughnut',{labels:(state.devices||[]).map(x=>x.name),datasets:[{data:(state.devices||[]).map(x=>x.visits),backgroundColor:['#4658ff','#0ea5e9','#10b981','#94a3b8'],borderWidth:0}]},{cutout:'60%',plugins:{legend:{display:true,position:'bottom'}}});document.getElementById('deviceNotes').innerHTML=(state.devices||[]).slice(0,4).map(x=>`<div class="mini-row"><span>${esc(x.name)}</span><strong>${fmt.format(x.visits)}</strong></div>`).join('');
    const siteCr=s?.visits?s.formSubmits/s.visits*100:0;document.getElementById('sourcesTable').innerHTML=(state.sources||[]).map(x=>{const cr=x.visits?x.conversions/x.visits*100:0,[l,c]=sourceQuality(x,siteCr);return `<tr><td>${esc(x.name)}</td><td>${fmt.format(x.visits)}</td><td>${fmt.format(x.users)}</td><td>${pct(x.bounce)}</td><td>${fmt.format(x.conversions)}</td><td>${pct(cr)}</td><td>${pill(l,c)}</td></tr>`}).join('')||'<tr><td colspan="7" class="empty-cell">Нет данных.</td></tr>';
    document.getElementById('regionList').innerHTML=(state.regions||[]).slice(0,10).map((x,i)=>`<div class="rank-row"><span class="rank-num">${i+1}</span><span>${esc(x.name)}</span><strong>${fmt.format(x.visits)}</strong></div>`).join('')||'<div class="empty-state">Нет данных.</div>';
    document.getElementById('goalsTable').innerHTML=(state.goals||[]).map(x=>{let note=x.category==='form'?'ключевая лид-цель':x.category==='email'?'контакт через email':'другая цель';return `<tr><td>${esc(x.name)}</td><td>${esc(x.type||'—')}</td><td>${esc(x.category||'other')}</td><td>${fmt.format(x.reaches)}</td><td>${pct(x.conversionRate)}</td><td>${esc(note)}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty-cell">Цели не загружены.</td></tr>';
    document.getElementById('pagesTable').innerHTML=(state.pages||[]).slice(0,100).map(p=>{const cr=p.visits?p.conversions/p.visits*100:0,[l,c]=pageSignal(p,siteCr);return `<tr><td class="url-cell" title="${esc(p.page)}">${esc(shortUrl(p.page))}</td><td>${fmt.format(p.visits)}</td><td>${pct(p.bounce)}</td><td>${num(p.depth).toFixed(2)}</td><td>${duration(p.duration)}</td><td>${fmt.format(p.conversions)}</td><td>${pct(cr)}</td><td>${pill(l,c)}</td></tr>`}).join('')||'<tr><td colspan="8" class="empty-cell">Нет данных страниц.</td></tr>';
    document.getElementById('searchPhrasesTable').innerHTML=(state.searchPhrases||[]).slice(0,60).map(x=>`<tr><td>${esc(x.phrase)}</td><td>${esc(x.engine)}</td><td>${fmt.format(x.visits)}</td><td>${pct(x.bounce)}</td><td>${duration(x.duration)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty-cell">Поисковые фразы Метрики не загрузились или скрыты поисковиком.</td></tr>';
    document.getElementById('utmTable').innerHTML=(state.utm||[]).slice(0,100).map(x=>`<tr><td>${esc(x.source)} / ${esc(x.medium)}</td><td>${esc(x.campaign)}</td><td>${fmt.format(x.visits)}</td><td>${pct(x.bounce)}</td><td>${fmt.format(x.conversions)}</td><td>${pct(x.visits?x.conversions/x.visits*100:0)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty-cell">UTM-данных пока нет.</td></tr>';
  }

  function seoSignal(q){if(q.delta<=-3&&q.shows>=20)return ['Падение','bad'];if(q.position>=4&&q.position<=15&&q.shows>=20)return ['Быстрый рост','warn'];if(q.position<=10&&q.shows>=30&&q.ctr<2)return ['Низкий CTR','warn'];if(q.delta>=3)return ['Рост','good'];return ['Норма','muted'];}
  function renderSeo(){const s=seoSummary();metricGrid('seoMetrics',[
    {title:'Показы',value:s?fmt.format(s.shows):'—',note:'по запросам'}, {title:'Клики',value:s?fmt.format(s.clicks):'—',note:'из поиска Яндекса'}, {title:'CTR',value:s?pct(s.ctr):'—',note:'сниппеты'}, {title:'Средняя позиция',value:s&&s.position?num(s.position).toFixed(1):'—',note:'взвешено по показам'}, {title:'Страниц в поиске',value:s?fmt.format(s.searchablePages||0):'—',note:'Вебмастер'}, {title:'Исключено',value:s?fmt.format(s.excludedPages||0):'—',note:'не участвуют в поиске'}, {title:'ИКС',value:s?fmt.format(s.sqi||0):'—',note:'качество сайта'}, {title:'Критические ошибки',value:s?fmt.format(num(s.fatal)+num(s.critical)):'—',note:'Fatal + Critical'}]);
    chart('seoIndexChart','line',{labels:(state.seoIndex||[]).map(x=>dateRu(x.date)),datasets:[{label:'Страницы в поиске',data:(state.seoIndex||[]).map(x=>x.pagesInSearch),borderColor:'#4658ff',backgroundColor:'rgba(70,88,255,.08)',fill:true,tension:.25}]});
    document.getElementById('seoProblems').innerHTML=(state.seoProblems||[]).length?(state.seoProblems||[]).slice(0,12).map(x=>issueHtml({level:x.severity==='FATAL'||x.severity==='CRITICAL'?'high':x.severity==='POSSIBLE_PROBLEM'?'medium':'low',title:x.code,text:`Статус: ${x.state||'—'}`,action:x.severity==='FATAL'||x.severity==='CRITICAL'?'Исправить до контентных работ.':'Проверить в Вебмастере.'})).join(''):'<div class="empty-state">Проблемы не загружены или отсутствуют.</div>';
    document.getElementById('seoPlan').innerHTML=seoRecommendations().map((x,i)=>`<div class="plan-card"><span class="plan-index">${i+1}</span><div><strong>${esc(x.title)}</strong><p>${esc(x.text)}</p><span>${esc(x.action)}</span></div></div>`).join('');
    const opp=(state.seo||[]).filter(q=>q.position>=4&&q.position<=15&&q.shows>=10).sort((a,b)=>b.shows-a.shows).slice(0,8);document.getElementById('seoOpportunities').innerHTML=opp.length?opp.map(q=>issueHtml({level:'medium',title:q.query,text:`Позиция ${q.position.toFixed(1)}, ${fmt.format(q.shows)} показов, CTR ${pct(q.ctr)}.`,action:q.position<=10?'Усилить сниппет и релевантность.':'Доработать страницу и внутренние ссылки.'})).join(''):'<div class="empty-state">Быстрые возможности пока не определены.</div>';
    chart('seoChart','bar',{labels:opp.slice(0,10).map(q=>truncate(q.query,28)),datasets:[{label:'Показы',data:opp.slice(0,10).map(q=>q.shows),backgroundColor:'#4658ff'}]});renderSeoTable();
  }
  function renderSeoTable(){const q=(document.getElementById('seoSearch')?.value||'').toLowerCase(),rows=(state.seo||[]).filter(x=>x.query.toLowerCase().includes(q)).slice(0,300);document.getElementById('seoTable').innerHTML=rows.map(x=>{const [l,c]=seoSignal(x);return `<tr><td>${esc(x.query)}</td><td>${fmt.format(x.shows)}</td><td>${fmt.format(x.clicks)}</td><td>${pct(x.ctr)}</td><td>${num(x.position).toFixed(1)}</td><td>${x.clickPosition?num(x.clickPosition).toFixed(1):'—'}</td><td class="${x.delta>0?'positive':x.delta<0?'negative':''}">${x.delta>0?'+':''}${num(x.delta).toFixed(1)}</td><td>${pill(l,c)}</td></tr>`}).join('')||'<tr><td colspan="8" class="empty-cell">Нет запросов.</td></tr>';}

  function renderAds(){const days=num(document.getElementById('periodSelect').value||30),rows=aggregateAds(days,adChannelFilter),t=adTotals(rows);metricGrid('adsMetrics',[
    {title:'Расход',value:rows.length?money.format(t.spend):'—',note:'только данные API'}, {title:'Показы',value:rows.length?fmt.format(t.impressions):'—',note:'реклама'}, {title:'Клики',value:rows.length?fmt.format(t.clicks):'—',note:'реклама'}, {title:'CTR',value:rows.length?pct(t.ctr):'—',note:'клики / показы'}, {title:'CPC',value:rows.length&&t.clicks?money.format(t.cpc):'—',note:'средняя цена клика'}, {title:'Конверсии',value:rows.length?fmt.format(t.conversions):'—',note:'цели'}, {title:'CVR',value:rows.length?pct(t.cvr):'—',note:'конверсии / клики'}, {title:'CPA',value:rows.length&&t.cpa!==null?money.format(t.cpa):'—',note:'расход / конверсии'}]);
    const channels=['Все',...[...new Set((state.adsMeta||[]).map(x=>x.channel))]];const tabs=document.getElementById('adChannelTabs');tabs.innerHTML=channels.map(c=>`<button class="channel-tab ${c===adChannelFilter?'active':''}" data-ad-channel="${esc(c)}">${esc(c)}</button>`).join('');tabs.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{adChannelFilter=b.dataset.adChannel;renderAds();}));
    const daily=rowsFor(state.adsDaily,days).filter(x=>adChannelFilter==='Все'||x.channel===adChannelFilter),dates=[...new Set(daily.map(x=>x.date))].sort(),byDate=d=>daily.filter(x=>x.date===d);chart('adsChart','bar',{labels:dates.map(dateRu),datasets:[{label:'Расход, ₽',data:dates.map(d=>sum(byDate(d),'spend')),backgroundColor:'rgba(70,88,255,.75)',yAxisID:'y'},{label:'Конверсии',data:dates.map(d=>sum(byDate(d),'conversions')),type:'line',borderColor:'#e35454',backgroundColor:'#e35454',tension:.25,yAxisID:'y1'}]},{plugins:{legend:{display:true,position:'bottom'}},scales:{x:{grid:{display:false}},y:{beginAtZero:true},y1:{beginAtZero:true,position:'right',grid:{drawOnChartArea:false}}}});
    document.getElementById('adsIssues').innerHTML=adsRecommendations(days).map(issueHtml).join('');
    const byChannel=[...new Set(rows.map(x=>x.channel))].map(ch=>({ch,t:adTotals(rows.filter(x=>x.channel===ch))}));document.getElementById('adChannelCompare').innerHTML=byChannel.length?byChannel.map(x=>`<div class="compare-card"><strong>${esc(x.ch)}</strong><span>Расход ${money.format(x.t.spend)}</span><span>Клики ${fmt.format(x.t.clicks)}</span><span>Конверсии ${fmt.format(x.t.conversions)}</span><span>CPA ${x.t.cpa!==null?money.format(x.t.cpa):'—'}</span></div>`).join(''):'<div class="empty-state">Нет данных рекламы.</div>';
    const directRows=rows.filter(x=>x.channel==='Яндекс Директ'&&x.clicks);document.getElementById('adBehavior').innerHTML=directRows.length?directRows.slice(0,6).map(x=>`<div class="mini-row"><span>${esc(x.name)}</span><strong>отказы ${x.bounceRate?pct(x.bounceRate):'—'} · глубина ${x.avgPageviews?x.avgPageviews.toFixed(2):'—'}</strong></div>`).join(''):'<div class="empty-state">Поведенческие метрики появятся из Директа после успешного Reports API.</div>';
    document.getElementById('adsTable').innerHTML=rows.length?rows.map(x=>{const [sl,sc]=normalizedStatus(x.status);let comment='Стабильно';if(sl==='Остановлена')comment='Историческая кампания';else if(sl==='Активна'&&x.spend>0&&x.conversions===0&&x.clicks>=10)comment='Расход без конверсий';else if(x.cpa&&t.cpa&&x.cpa>t.cpa*1.5)comment='CPA выше среднего';return `<tr><td>${esc(x.channel)}</td><td>${esc(x.name)}</td><td>${pill(sl,sc)}</td><td>${fmt.format(x.impressions)}</td><td>${fmt.format(x.clicks)}</td><td>${pct(x.ctr)}</td><td>${money.format(x.spend)}</td><td>${x.clicks?money.format(x.cpc):'—'}</td><td>${fmt.format(x.conversions)}</td><td>${pct(x.cvr)}</td><td>${x.cpa!==null?money.format(x.cpa):'—'}</td><td>${x.bounceRate?pct(x.bounceRate):'—'}</td><td>${x.avgPageviews?x.avgPageviews.toFixed(2):'—'}</td><td>${esc(comment)}</td></tr>`}).join(''):'<tr><td colspan="14" class="empty-cell">Данные рекламы пока не загружены.</td></tr>';
  }

  function classifyContent(post){const t=String(post.title||'').toLowerCase();if(/тест|опрос|собери|угада|кроссворд|что здесь не так|правда или миф|выберите|голосован/.test(t))return 'Интерактив';if(/легионел|истори|древн|рим|почему|наук|исследован|бактери|физик|хими/.test(t))return 'Научпоп / история';if(/смесител|подводк|лейк|душ|арматур|излив|кран|сантехник|товар|модель/.test(t))return 'Товар / экспертность';if(/дилер|опт|ассортимент|магазин|скидк|акци|промокод|заказ|партнер/.test(t))return 'Продажи / B2B';if(/производств|цех|завод|испытан|контрол|технолог/.test(t))return 'Производство';if(/команд|компан|новост|поздрав|выставк|мероприят/.test(t))return 'Компания';return 'Другое';}
  function formatContent(post){if(post.mediaType&&post.mediaType!=='attachment')return ({image:'Фото',video:'Видео',poll:'Опрос',text:'Текст'}[post.mediaType]||post.mediaType);const t=String(post.title||'').toLowerCase();if(/опрос|голосован|выберите/.test(t))return 'Опрос';return 'Текст';}
  function socialPostRows(days){const raw=rowsFor(state.social,days);const byCh={};raw.forEach(x=>(byCh[x.channel]||(byCh[x.channel]=[])).push(x));return raw.map(x=>{const peers=byCh[x.channel]||[],mv=median(peers.map(p=>num(p.views)).filter(v=>v>0))||1,eng=num(x.reactions)+num(x.comments)+num(x.shares),me=median(peers.map(p=>num(p.reactions)+num(p.comments)+num(p.shares)).filter(v=>v>0));const viewIndex=num(x.views)/mv*100,engIndex=me?eng/me*100:null,index=clamp(me?viewIndex*.7+engIndex*.3:viewIndex,0,999);return {...x,eng,er:num(x.views)?eng/num(x.views)*100:0,index,topic:classifyContent(x),format:formatContent(x)};});}
  function postRecommendation(post){
    if(!num(post.views)) return 'Публичный источник не отдал просмотры: оценивать по теме/формату и проверить статистику площадки вручную.';
    if(post.index>=150) return `Сильный результат для ${post.channel}: повторить тему и формат в новом сюжете, сохранив первый экран/хук.`;
    if(post.index<70){
      if((post.title||'').length<55) return 'Слабее обычного: усилить первый тезис — добавить конкретную пользу, конфликт или вопрос в первые 1–2 строки.';
      if(post.format==='Текст') return 'Слабее обычного: протестировать визуал/карусель и сократить вступление до главной мысли.';
      return 'Слабее обычного: изменить хук и CTA; сравнить с сильными постами этого канала по теме и времени публикации.';
    }
    if(post.er<0.5 && num(post.views)>=50) return 'Просмотры есть, взаимодействий мало: добавить вопрос, выбор или конкретный CTA в конце.';
    return 'Результат около нормы канала: оставить тему в сетке и протестировать другой хук или формат.';
  }
  function groupContent(rows,key){const map=new Map();rows.forEach(x=>{const k=x[key]||'Другое',v=map.get(k)||{name:k,count:0,views:0,index:0,eng:0};v.count++;v.views+=num(x.views);v.index+=num(x.index);v.eng+=num(x.eng);map.set(k,v)});return [...map.values()].map(x=>({...x,avgViews:x.count?x.views/x.count:0,avgIndex:x.count?x.index/x.count:0})).sort((a,b)=>b.avgIndex-a.avgIndex);}
  function socialContentInsights(days,posts,channels){const out=[];for(const ch of channels){const prev=socialChannelSummary(days,ch.channel,days),dv=prev?relDelta(ch.views,prev.views):null;if(dv!==null&&dv<-25)out.push({level:'medium',title:`${ch.channel}: просмотры снизились`,text:`${dv.toFixed(0)}% к предыдущему периоду. Публикаций: ${ch.posts}.`,action:`Сравнить темы и формат сильных публикаций ${ch.channel} с текущей сеткой.`});else if(dv!==null&&dv>30)out.push({level:'low',title:`${ch.channel}: рост просмотров`,text:`+${dv.toFixed(0)}% к предыдущему периоду.`,action:'Зафиксировать темы, формат и частоту публикаций, которые дали рост.'});if(ch.posts>0&&ch.posts<Math.max(1,Math.floor(days/14)))out.push({level:'medium',title:`${ch.channel}: низкая частота`,text:`Только ${ch.posts} публикаций за ${days} дней.`,action:'Проверить, соответствует ли частота контент-плану и хватает ли касаний с аудиторией.'});}
    const themes=groupContent(posts,'topic');if(themes[0]&&themes[0].count>=2&&themes[0].avgIndex>=125)out.push({level:'low',title:`Сильная тема: ${themes[0].name}`,text:`Средний индекс ${themes[0].avgIndex.toFixed(0)} при ${themes[0].count} публикациях.`,action:'Сделать ещё 1–2 материала в этой тематике и проверить, повторяется ли эффект.'});const weak=themes.filter(x=>x.count>=2).sort((a,b)=>a.avgIndex-b.avgIndex)[0];if(weak&&weak.avgIndex<70)out.push({level:'medium',title:`Слабая тема: ${weak.name}`,text:`Средний индекс ${weak.avgIndex.toFixed(0)} — заметно ниже обычного уровня собственных каналов.`,action:'Не увеличивать долю темы без нового угла подачи; проверить хук, визуал и формат.'});const best=[...posts].sort((a,b)=>b.index-a.index)[0];if(best)out.push({level:'low',title:`Лучший пост: ${best.channel}`,text:`«${truncate(best.title,90)}» — индекс ${best.index.toFixed(0)} относительно обычных публикаций этого же канала.`,action:`Разобрать тему «${best.topic}», формат «${best.format}» и первый экран/хук.`});return out.slice(0,8);}
  function renderSocial(){const days=num(document.getElementById('periodSelect').value||30),s=socialSummary(days),p=socialSummary(days,days),channels=socialChannels(days),posts=socialPostRows(days).sort((a,b)=>b.index-a.index);metricGrid('socialMetrics',[
    {title:'Каналы с данными',value:s?fmt.format(s.channels):'—',note:'VK + Telegram + MAX'}, {title:'Публикации',value:s?fmt.format(s.posts):'—',note:`за ${days} дней`}, {title:'Просмотры',value:s?fmt.format(s.views):'—',delta:s&&p?relDelta(s.views,p.views):null,note:'по доступным метрикам'}, {title:'Взаимодействия',value:s?fmt.format(s.interactions):'—',note:'реакции + комментарии + репосты'}, {title:'Среднее / пост',value:s?fmt.format(Math.round(s.avgViews||0)):'—',note:'просмотров'}, {title:'ER',value:s?pct(s.er):'—',note:'по доступным реакциям'}, {title:'VK подписчики',value:(channels.find(x=>x.channel==='VK')?.followers)?fmt.format(channels.find(x=>x.channel==='VK').followers):'—',note:'если доступны VK API'}, {title:'Telegram подписчики',value:(channels.find(x=>x.channel==='Telegram')?.followers)?fmt.format(channels.find(x=>x.channel==='Telegram').followers):'—',note:'из публичного preview'}]);
    document.getElementById('socialChannelCompare').innerHTML=channels.length?channels.map(ch=>`<div class="compare-card"><strong>${esc(ch.channel)}</strong><span>${fmt.format(ch.posts)} публикаций</span><span>${fmt.format(ch.views)} просмотров</span><span>${fmt.format(ch.interactions)} взаимодействий</span><span>Среднее ${fmt.format(Math.round(ch.avgViews||0))} / пост</span>${ch.reach?`<span>Охват ${fmt.format(ch.reach)}</span>`:''}${ch.followers?`<span>Подписчики ${fmt.format(ch.followers)}</span>`:''}</div>`).join(''):'<div class="empty-state">Синхронизируйте хотя бы один социальный канал.</div>';
    const daily=rowsFor(state.socialDaily,days),dates=[...new Set(daily.map(x=>x.date))].sort(),chs=[...new Set(daily.map(x=>x.channel))],palette=['#4658ff','#0ea5e9','#7c3aed','#f59e0b'];chart('socialDailyChart','line',{labels:dates.map(dateRu),datasets:chs.map((ch,i)=>({label:ch,data:dates.map(d=>sum(daily.filter(x=>x.channel===ch&&x.date===d),'views')),borderColor:palette[i%palette.length],tension:.25}))},{plugins:{legend:{display:true,position:'bottom'}}});
    const themes=groupContent(posts,'topic'),formats=groupContent(posts,'format');document.getElementById('contentThemeGrid').innerHTML=themes.length?themes.slice(0,6).map(x=>`<div class="compare-card"><strong>${esc(x.name)}</strong><span>${x.count} публикаций</span><span>Индекс ${x.avgIndex.toFixed(0)}</span><span>${fmt.format(Math.round(x.avgViews))} просм. / пост</span></div>`).join(''):'<div class="empty-state">Недостаточно публикаций.</div>';document.getElementById('contentFormatGrid').innerHTML=formats.length?formats.slice(0,6).map(x=>`<div class="compare-card"><strong>${esc(x.name)}</strong><span>${x.count} публикаций</span><span>Индекс ${x.avgIndex.toFixed(0)}</span><span>${fmt.format(Math.round(x.avgViews))} просм. / пост</span></div>`).join(''):'<div class="empty-state">Недостаточно публикаций.</div>';
    const best=posts.slice(0,6);document.getElementById('topPostCards').innerHTML=best.length?best.map((x,i)=>`<div class="top-post"><span>#${i+1} · ${esc(x.channel)}</span><strong>${x.postUrl?`<a href="${esc(x.postUrl)}" target="_blank" rel="noopener">${esc(truncate(x.title,120))}</a>`:esc(truncate(x.title,120))}</strong><small>${dateRu(x.date)} · ${esc(x.topic)} · ${esc(x.format)}</small><b>Индекс ${x.index.toFixed(0)} · ${fmt.format(x.views)} просмотров</b></div>`).join(''):'<div class="empty-state">Нет публикаций за период.</div>';
    const issues=socialContentInsights(days,posts,channels);document.getElementById('contentInsights').innerHTML=issues.length?issues.map(issueHtml).join(''):'<div class="empty-state">Нужны публикации минимум из одного канала для комментария.</div>';
    const medByCh=Object.fromEntries(channels.map(c=>[c.channel,median(posts.filter(x=>x.channel===c.channel).map(x=>x.index))||100]));document.getElementById('socialTable').innerHTML=posts.length?posts.map(x=>{const label=x.index>=140?'Сильный':x.index<70?'Слабый':'Средний';return `<tr><td>${pill(x.channel,x.channel==='VK'?'info':x.channel==='Telegram'?'good':'warn')}</td><td>${x.postUrl?`<a href="${esc(x.postUrl)}" target="_blank" rel="noopener">${esc(truncate(x.title,110))}</a>`:esc(truncate(x.title,110))}</td><td>${esc(x.topic)}</td><td>${esc(x.format)}</td><td>${dateRu(x.date)}</td><td>${fmt.format(x.views)}</td><td>${num(x.reactions)?fmt.format(x.reactions):'—'}</td><td>${num(x.comments)?fmt.format(x.comments):'—'}</td><td>${num(x.shares)?fmt.format(x.shares):'—'}</td><td>${x.index.toFixed(0)}</td><td>${pill(label,label==='Сильный'?'good':label==='Слабый'?'warn':'info')}</td><td class="advice-cell">${esc(postRecommendation(x))}</td></tr>`}).join(''):'<tr><td colspan="12" class="empty-cell">Нет публикаций.</td></tr>';
  }

  function renderEmail(){const days=num(document.getElementById('periodSelect').value||30),e=emailSummary(days),p=emailSummary(days,days);metricGrid('emailMetrics',[
    {title:'Рассылки',value:e?fmt.format(e.campaigns):'—',note:`за ${days} дней`}, {title:'Отправлено',value:e?fmt.format(e.sent):'—',note:'UniSender'}, {title:'Доставляемость',value:e?pct(e.delivery):'—',note:'delivered / sent'}, {title:'Open Rate',value:e?pct(e.openRate):'—',delta:e&&p?relDelta(e.openRate,p.openRate):null,note:'уникальные открытия'}, {title:'CTR',value:e?pct(e.ctr):'—',delta:e&&p?relDelta(e.ctr,p.ctr):null,note:'клики / доставленные'}, {title:'CTOR',value:e?pct(e.ctor):'—',note:'клики / открывшие'}, {title:'Отписки',value:e?pct(e.unsubRate,2):'—',note:'от доставленных'}, {title:'Спам',value:e?pct(e.spamRate,2):'—',note:'от доставленных'}]);
    const rows=rowsFor(state.email,days).sort((a,b)=>String(a.date).localeCompare(String(b.date)));chart('emailChart','bar',{labels:rows.map(x=>dateRu(x.date)),datasets:[{label:'Open Rate',data:rows.map(x=>x.delivered?x.opened/x.delivered*100:0),backgroundColor:'rgba(70,88,255,.7)'},{label:'CTR',data:rows.map(x=>x.delivered?x.clicked/x.delivered*100:0),backgroundColor:'rgba(14,165,233,.75)'}]},{plugins:{legend:{display:true,position:'bottom'}},scales:{x:{grid:{display:false}},y:{beginAtZero:true,ticks:{callback:v=>`${v}%`}}}});
    document.getElementById('emailIssues').innerHTML=emailRecommendations(days).map(issueHtml).join('');const medCtr=median(rows.filter(x=>x.delivered).map(x=>x.clicked/x.delivered*100));document.getElementById('emailTable').innerHTML=rows.length?rows.slice().reverse().map(x=>{const delivery=x.sent?x.delivered/x.sent*100:0,or=x.delivered?x.opened/x.delivered*100:0,ctr=x.delivered?x.clicked/x.delivered*100:0,ctor=x.opened?x.clicked/x.opened*100:0,unsub=x.delivered?x.unsub/x.delivered*100:0,spam=x.delivered?x.spam/x.delivered*100:0;let l='Норма',c='info';if(delivery<95||spam>.1){l='Проверить';c='bad'}else if(medCtr&&ctr>medCtr*1.4){l='Сильная';c='good'}return `<tr><td>${x.reportUrl?`<a href="${esc(x.reportUrl)}" target="_blank" rel="noopener">${esc(x.name)}</a>`:esc(x.name)}</td><td>${dateRu(x.date)}</td><td>${fmt.format(x.sent)}</td><td>${fmt.format(x.delivered)}</td><td>${pct(delivery)}</td><td>${pct(or)}</td><td>${pct(ctr)}</td><td>${pct(ctor)}</td><td>${pct(unsub,2)}</td><td>${pct(spam,2)}</td><td>${pill(l,c)}</td></tr>`}).join(''):'<tr><td colspan="11" class="empty-cell">Нет рассылок.</td></tr>';
    const names=Object.fromEntries((state.email||[]).map(x=>[String(x.id),x.name]));document.getElementById('emailLinksTable').innerHTML=(state.emailLinks||[]).slice(0,80).map(x=>`<tr><td class="url-cell"><a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(shortUrl(x.url))}</a></td><td>${esc(names[String(x.campaignId)]||x.campaignId)}</td><td>${fmt.format(x.clicks)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty-cell">Данные по ссылкам появятся после синхронизации UniSender.</td></tr>';
  }

  function autoTasks(){const days=num(document.getElementById('periodSelect').value||30),pack=insights(days),all=[...pack.issues,...seoRecommendations(),...adsRecommendations(days),...socialContentInsights(days,socialPostRows(days),socialChannels(days)),...emailRecommendations(days)],seen=new Set(),tasks=[];for(const x of all){const title=x.action||x.title;if(!title||seen.has(title))continue;seen.add(title);tasks.push({id:`auto-${hash(title)}`,title,priority:x.level==='high'?'high':x.level==='medium'?'medium':'low',source:x.area||'Автоаналитика',reason:x.title});}return tasks.slice(0,30);}
  function renderTasks(){const items=[...autoTasks(),...(local.manualTasks||[])],done=local.doneTasks||{},ord={high:0,medium:1,low:2};items.sort((a,b)=>ord[a.priority]-ord[b.priority]);document.getElementById('taskList').innerHTML=items.length?items.map(x=>`<div class="task-item ${done[x.id]?'done':''}"><input type="checkbox" data-task="${esc(x.id)}" ${done[x.id]?'checked':''}/><div><div class="task-title">${esc(x.title)}</div><div class="task-meta">${esc(x.source||'')} ${x.reason?`· ${esc(x.reason)}`:''}</div></div><span class="priority ${x.priority}">${x.priority==='high'?'Высокий':x.priority==='medium'?'Средний':'Низкий'}</span></div>`).join(''):'<div class="empty-state">Задач нет.</div>';document.getElementById('focusSteps').innerHTML=items.filter(x=>!done[x.id]).slice(0,6).map(x=>`<li>${esc(x.title)}</li>`).join('')||'<li>Критичных задач по доступным данным нет.</li>';document.querySelectorAll('[data-task]').forEach(c=>c.addEventListener('change',e=>{local.doneTasks=local.doneTasks||{};local.doneTasks[e.target.dataset.task]=e.target.checked;saveLocal();renderTasks();}));}

  function reportData(days){const site=siteSummary(days),prev=siteSummary(days,days),seo=seoSummary(),ads=aggregateAds(days),social=socialSummary(days),email=emailSummary(days),pack=insights(days);return {generatedAt:new Date().toISOString(),days,score:marketingScore(days),site,sitePrevious:prev,seo,ads,adTotals:adTotals(ads),social,email,issues:pack.issues,positives:pack.positives,seoPlan:seoRecommendations(),adPlan:adsRecommendations(days),socialPlan:socialContentInsights(days,socialPostRows(days),socialChannels(days)),emailPlan:emailRecommendations(days),tasks:autoTasks(),comment:managerText(days),syncLog:state.syncLog};}
  function selectedSections(){return [...document.querySelectorAll('.reportCheck:checked')].map(x=>x.value);}
  function renderReports(){const days=num(document.getElementById('reportPeriod').value||30),d=reportData(days),preview=[];preview.push(`<div class="preview-score"><strong>${d.score}/100</strong><span>Marketing health</span></div>`);if(d.site)preview.push(`<div class="preview-row"><span>Визиты</span><strong>${fmt.format(d.site.visits)}</strong></div><div class="preview-row"><span>Заявки</span><strong>${fmt.format(d.site.formSubmits)}</strong></div>`);if(d.seo)preview.push(`<div class="preview-row"><span>SEO клики</span><strong>${fmt.format(d.seo.clicks)}</strong></div>`);if(d.adTotals.spend)preview.push(`<div class="preview-row"><span>Расход рекламы</span><strong>${money.format(d.adTotals.spend)}</strong></div>`);preview.push(`<div class="preview-row"><span>Проблемы высокого приоритета</span><strong>${d.issues.filter(x=>x.level==='high').length}</strong></div>`);document.getElementById('reportPreview').innerHTML=preview.join('');document.getElementById('managerComment').innerHTML=d.comment.map(x=>`<p>${esc(x)}</p>`).join('')||'<div class="empty-state">Недостаточно данных.</div>';}
  function tableHtml(headers,rows){return `<table class="pdf-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>`;}
  function buildReportHtml(){const days=num(document.getElementById('reportPeriod').value||30),d=reportData(days),sel=selectedSections(),title=esc(document.getElementById('reportName').value||'Маркетинговый отчёт'),k=(l,v,n='')=>`<div class="pdf-kpi"><span>${esc(l)}</span><strong>${v}</strong><small>${esc(n)}</small></div>`;let h=`<div class="pdf-report"><div class="pdf-brand">CS Marketing by skayfall</div><h1>${title}</h1><div class="report-date">Последние ${days} дней · сформирован ${new Date().toLocaleString('ru-RU')}</div>`;
    if(sel.includes('summary')){h+=`<h2>Резюме</h2><div class="pdf-kpis">${k('Marketing health',`${d.score}/100`)}${k('Визиты',d.site?fmt.format(d.site.visits):'—')}${k('Заявки',d.site?fmt.format(d.site.formSubmits):'—')}${k('SEO-клики',d.seo?fmt.format(d.seo.clicks):'—')}${k('Расход рекламы',d.adTotals.spend?money.format(d.adTotals.spend):'—')}</div><div class="pdf-comment">${d.comment.map(x=>`<p>${esc(x)}</p>`).join('')}</div>`;}
    if(sel.includes('site')&&d.site){const cr=d.site.visits?d.site.formSubmits/d.site.visits*100:0;h+=`<h2>Сайт</h2><div class="pdf-kpis">${k('Посетители',fmt.format(d.site.users))}${k('Отказы',pct(d.site.bounce))}${k('Глубина',d.site.depth.toFixed(2))}${k('Время',duration(d.site.duration))}${k('CR формы',pct(cr))}</div>`;const rows=(state.sources||[]).slice(0,8).map(x=>`<tr><td>${esc(x.name)}</td><td>${fmt.format(x.visits)}</td><td>${pct(x.bounce)}</td><td>${fmt.format(x.conversions)}</td></tr>`);h+=`<h3>Источники</h3>${tableHtml(['Источник','Визиты','Отказы','Цели'],rows)}`;}
    if(sel.includes('seo')&&d.seo){h+=`<h2>SEO</h2><div class="pdf-kpis">${k('Показы',fmt.format(d.seo.shows))}${k('Клики',fmt.format(d.seo.clicks))}${k('CTR',pct(d.seo.ctr))}${k('Позиция',d.seo.position?d.seo.position.toFixed(1):'—')}${k('В поиске',fmt.format(d.seo.searchablePages||0))}</div>`;const rows=(state.seo||[]).slice(0,10).map(q=>`<tr><td>${esc(q.query)}</td><td>${fmt.format(q.shows)}</td><td>${fmt.format(q.clicks)}</td><td>${pct(q.ctr)}</td><td>${q.position.toFixed(1)}</td><td>${q.delta>0?'+':''}${q.delta.toFixed(1)}</td></tr>`);h+=tableHtml(['Запрос','Показы','Клики','CTR','Позиция','Δ'],rows);}
    if(sel.includes('ads')){h+=`<h2>Реклама</h2><div class="pdf-kpis">${k('Расход',money.format(d.adTotals.spend))}${k('Клики',fmt.format(d.adTotals.clicks))}${k('CTR',pct(d.adTotals.ctr))}${k('Конверсии',fmt.format(d.adTotals.conversions))}${k('CPA',d.adTotals.cpa!==null?money.format(d.adTotals.cpa):'—')}</div>`;const rows=d.ads.slice(0,12).map(x=>`<tr><td>${esc(x.channel)}</td><td>${esc(x.name)}</td><td>${money.format(x.spend)}</td><td>${fmt.format(x.clicks)}</td><td>${fmt.format(x.conversions)}</td><td>${x.cpa!==null?money.format(x.cpa):'—'}</td></tr>`);h+=tableHtml(['Канал','Кампания','Расход','Клики','Конверсии','CPA'],rows);}
    if(sel.includes('social')&&d.social){h+=`<h2>Соцсети</h2><div class="pdf-kpis">${k('Каналы',fmt.format(d.social.channels))}${k('Публикации',fmt.format(d.social.posts))}${k('Просмотры',fmt.format(d.social.views))}${k('Взаимодействия',fmt.format(d.social.interactions))}${k('ER',pct(d.social.er))}</div>`;const sr=d.social.byChannel.map(x=>`<tr><td>${esc(x.channel)}</td><td>${fmt.format(x.posts)}</td><td>${fmt.format(x.views)}</td><td>${fmt.format(x.interactions)}</td><td>${fmt.format(Math.round(x.avgViews||0))}</td></tr>`);h+=tableHtml(['Канал','Публикации','Просмотры','Взаимодействия','Среднее / пост'],sr);const sp=socialPostRows(days).sort((a,b)=>b.index-a.index).slice(0,5).map(x=>`<tr><td>${esc(x.channel)}</td><td>${esc(truncate(x.title,70))}</td><td>${esc(x.topic)}</td><td>${fmt.format(x.views)}</td><td>${x.index.toFixed(0)}</td></tr>`);if(sp.length)h+=`<h3>Сильные публикации</h3>${tableHtml(['Канал','Публикация','Тема','Просмотры','Индекс'],sp)}`;}
    if(sel.includes('email')&&d.email)h+=`<h2>Email</h2><div class="pdf-kpis">${k('Рассылки',fmt.format(d.email.campaigns))}${k('Delivery',pct(d.email.delivery))}${k('Open Rate',pct(d.email.openRate))}${k('CTR',pct(d.email.ctr))}${k('CTOR',pct(d.email.ctor))}</div>`;
    if(sel.includes('plan')){const plan=[...d.issues,...d.seoPlan,...d.adPlan,...d.socialPlan,...d.emailPlan].filter((x,i,a)=>a.findIndex(y=>y.title===x.title)===i).slice(0,12);h+=`<h2>План действий</h2><ol class="pdf-plan">${plan.map(x=>`<li><strong>${esc(x.title)}</strong><span>${esc(x.action||x.text)}</span></li>`).join('')}</ol>`;}
    return h+'</div>';
  }
  async function downloadPdf(){const box=document.getElementById('reportCanvas');box.innerHTML=buildReportHtml();if(window.html2pdf)await html2pdf().set({margin:[8,8,8,8],filename:`cs-marketing-${iso(new Date())}.pdf`,image:{type:'jpeg',quality:.96},html2canvas:{scale:2,useCORS:true},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'}}).from(box.firstElementChild).save();else window.print();}
  function downloadBlob(content,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000);}
  function downloadComment(){const days=num(document.getElementById('reportPeriod').value||30),text=managerText(days).join('\n\n');downloadBlob('\uFEFF'+text,`cs-marketing-comment-${iso(new Date())}.txt`,'text/plain;charset=utf-8');}
  function downloadJson(){const days=num(document.getElementById('reportPeriod').value||30);downloadBlob(JSON.stringify(reportData(days),null,2),`cs-marketing-${iso(new Date())}.json`,'application/json');}
  function downloadCsv(){const days=num(document.getElementById('reportPeriod').value||30),d=reportData(days),rows=[['section','metric','value'],['site','visits',d.site?.visits??''],['site','users',d.site?.users??''],['site','forms',d.site?.formSubmits??''],['site','email_clicks',d.site?.emailClicks??''],['seo','shows',d.seo?.shows??''],['seo','clicks',d.seo?.clicks??''],['ads','spend',d.adTotals.spend],['ads','clicks',d.adTotals.clicks],['ads','conversions',d.adTotals.conversions],['social','views',d.social?.views??''],['social','posts',d.social?.posts??''],['email','open_rate',d.email?.openRate??''],['email','ctr',d.email?.ctr??'']];downloadBlob('\uFEFF'+rows.map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(';')).join('\n'),`cs-marketing-${iso(new Date())}.csv`,'text/csv;charset=utf-8');}

  const integrations=[
    ['metrika','Яндекс Метрика','Сайт: посещаемость, поведение, цели, UTM, поисковые фразы'],['webmaster','Яндекс Вебмастер','SEO: запросы, позиции, индексация, диагностика'],['direct','Яндекс Директ','Кампании, расходы, клики, конверсии, поведение после клика'],['vkads','VK Реклама (ads.vk.com)','Рекламный контур: кампании, расходы и статистика; access token обновляется автоматически'],['vksocial','VK — публичный контент','При каждом обновлении приложение проверяет https://vk.ru/centr_santechniki; API сообщества используется только как дополнительный источник'],['telegram','Telegram — публичный контент','При каждом обновлении проверяется https://t.me/CS_trade_official и сохраняются названия постов и доступные просмотры'],['maxsocial','MAX — публичный контент','При каждом обновлении проверяется https://max.ru/id7724208038_biz; Bot API используется дополнительно, если настроен'],['dzen','Дзен — публичный контент','При каждом обновлении проверяется https://dzen.ru/centr_santehniki и сохраняются доступные метрики публикаций'],['unisender','UniSender','Рассылки, доставляемость, открытия, клики и ссылки']
  ];
  function renderIntegrations(){const grid=document.getElementById('integrationGrid');if(!grid)return;grid.innerHTML=integrations.map(([id,name,desc])=>{const s=apiStatus.integrations?.[id]||{},ok=Boolean(s.configured??s.connected),cls=!ok?'warn':s.status==='error'?'bad':s.status==='partial'||s.status==='pending'?'warn':'good',label=!ok?'Нужны доступы':s.status?statusLabel(s.status):'Доступы есть';return `<article class="integration-card"><div class="integration-title"><strong>${name}</strong>${pill(label,cls)}</div><p>${esc(desc)}</p><div class="integration-meta">${s.lastSync?`Последняя синхронизация: ${esc(dateTimeRu(s.lastSync))}`:'Синхронизация ещё не выполнялась'}${s.message?`<br>${esc(s.message)}`:''}${s.missing?.length?`<br>Не хватает: ${s.missing.map(esc).join(', ')}`:''}</div><button class="secondary-btn sync-one" data-source="${id}" ${ok?'':'disabled'}>Синхронизировать</button></article>`}).join('');grid.querySelectorAll('.sync-one').forEach(b=>b.addEventListener('click',()=>syncOne(b.dataset.source)));
    const required=[['ADMIN_PASSWORD','Secret','авторизация'],['ADMIN_USERNAME','Text','логин'],['SESSION_SECRET','Secret','сессия'],['SITE_URL','Text','поиск счётчика/хоста'],['YANDEX_TOKEN','Secret','Метрика + Вебмастер + Директ'],['UNISENDER_API_KEY','Secret','UniSender'],['VK_ADS_CLIENT_ID','Text','VK Реклама OAuth'],['VK_ADS_CLIENT_SECRET','Secret','VK Реклама OAuth'],['VK_COMMUNITY_TOKEN','Secret','статистика/идентификация VK-сообщества'],['TELEGRAM_CHANNEL_URL','Text','публичный Telegram-канал'],['MAX_BOT_TOKEN','Secret','MAX Bot API'],['MAX_CHANNEL_ID','Text','ID канала MAX']];
    const optional=[['VK_SERVICE_TOKEN','Secret','опционально: надёжное чтение постов VK через wall.get'],['VK_USER_TOKEN','Secret','опционально: пользовательский read-token для постов VK'],['VK_COMMUNITY_URL','Text','опционально: публичная страница VK для резервного чтения постов'],['VK_GROUP_ID','Text','опционально: ID сообщества, если автоопределение не сработало']];
    const all=[...required,...optional];document.getElementById('credentialChecklist').innerHTML=all.map(([k,t,use])=>`<tr><td><code>${k}</code></td><td>${t}</td><td>${apiStatus.runtime?.[k]?pill('Есть','good'):pill(optional.some(x=>x[0]===k)?'Опционально':'Нет',optional.some(x=>x[0]===k)?'info':'bad')}</td><td>${esc(use)}</td></tr>`).join('');const missing=required.filter(([k])=>!apiStatus.runtime?.[k]).map(x=>x[0]);document.getElementById('runtimeSummary').innerHTML=missing.length?`Не хватает обязательных параметров: <strong>${missing.map(esc).join(', ')}</strong>`:'<strong>Все обязательные параметры текущей конфигурации присутствуют.</strong>';
    document.getElementById('syncLogTable').innerHTML=(state.syncLog||[]).length?(state.syncLog||[]).map(x=>`<tr><td>${esc(x.source)}</td><td>${esc(dateTimeRu(x.lastSync))}</td><td>${pill(statusLabel(x.status),x.status==='ok'?'good':x.status==='error'?'bad':'warn')}</td><td>${esc(x.message||'')}</td></tr>`).join(''):'<tr><td colspan="4" class="empty-cell">Журнал пока пуст.</td></tr>';renderHealth();}

  function renderAll(){renderOverview();renderSite();renderSeo();renderAds();renderSocial();renderEmail();renderTasks();renderReports();renderIntegrations();}
  function navigate(view){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===view));document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const copy={overview:['Обзор','Состояние сайта, обращения и то, как люди вас находят.'],site:['Сайт','Полная Метрика: поведение, источники, страницы, цели, UTM и поисковые фразы.'],seo:['SEO','Вебмастер: запросы, позиции, индексация, диагностика и план изменений.'],ads:['Реклама','Яндекс Директ и VK Реклама: деньги, качество трафика и результат.'],social:['Соцсети','VK, Telegram, MAX и Дзен: публикации, просмотры, темы, форматы и рекомендации по каждому посту.'],email:['Email','UniSender: доставляемость, открытия, клики, ссылки и качество рассылок.'],tasks:['Задачи','Автоматический рабочий план по проблемам из аналитики.'],reports:['Отчёты','Резюме руководителю, комментарии, PDF и выгрузки.'],integrations:['Интеграции','Состояние API, runtime-параметры и журнал синхронизаций.']}[view];document.getElementById('pageTitle').textContent=copy[0];document.getElementById('pageSubtitle').textContent=copy[1];document.getElementById('sidebar').classList.remove('open');}
  function shortUrl(v){try{const u=new URL(v);return u.pathname==='/'?u.hostname:`${u.hostname}${u.pathname}`;}catch{return truncate(v,58)}}
  function truncate(s,n){const x=String(s||'');return x.length>n?`${x.slice(0,n-1)}…`:x;}
  function hash(s){let h=2166136261;for(const c of String(s)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return (h>>>0).toString(36);}

  document.getElementById('loginForm').addEventListener('submit',login);
  document.getElementById('logoutBtn').addEventListener('click',logout);
  document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));
  document.getElementById('mobileMenuBtn').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
  document.getElementById('periodSelect').addEventListener('change',renderAll);
  document.getElementById('seoSearch').addEventListener('input',renderSeoTable);
  document.getElementById('syncBtn').addEventListener('click',syncAll);
  document.getElementById('syncAllBtn').addEventListener('click',syncAll);
  document.getElementById('quickReportBtn').addEventListener('click',()=>{navigate('reports');renderReports()});
  document.getElementById('generateReportBtn').addEventListener('click',downloadPdf);
  document.getElementById('downloadCommentBtn').addEventListener('click',downloadComment);
  document.getElementById('downloadJsonBtn').addEventListener('click',downloadJson);
  document.getElementById('downloadCsvBtn').addEventListener('click',downloadCsv);
  document.getElementById('reportPeriod').addEventListener('change',renderReports);
  document.getElementById('reportName').addEventListener('input',renderReports);
  document.querySelectorAll('.reportCheck').forEach(x=>x.addEventListener('change',renderReports));
  document.getElementById('addTaskBtn').addEventListener('click',()=>document.getElementById('taskDialog').showModal());
  document.getElementById('taskForm').addEventListener('submit',e=>{e.preventDefault();const title=document.getElementById('taskTitleInput').value.trim();if(!title)return;local.manualTasks=local.manualTasks||[];local.manualTasks.push({id:`manual-${Date.now()}`,title,priority:document.getElementById('taskPriorityInput').value,source:'Своя задача'});saveLocal();document.getElementById('taskTitleInput').value='';document.getElementById('taskDialog').close();renderTasks();});

  initAuth();
})();
